import assert from 'node:assert/strict';
import { ToyRoomPhase } from '../src/js/toy-room/ToyRoomPhase.js';
import { ToyRoomArenaPhase, ARENA_VICTORY_FADE_DURATION } from '../src/js/toy-room/ToyRoomArenaPhase.js';

const starts = [];
const createChasePhase = config => ({
  campaign: Boolean(config.campaign),
  active: true,
  disposed: false,
  start(saved) { starts.push({ campaign: this.campaign, saved }); return Promise.resolve(); },
  snapshot() { return { version: 1, state: { stage: 'BEAR_DOWN' } }; },
  destroy() { this.disposed = true; }
});

function makeRoom() {
  const canvas = {
    width: 960, height: 540, getContext: () => ({}),
    addEventListener() {}, removeEventListener() {}
  };
  return new ToyRoomPhase(canvas, null, null, () => {}, {
    bindInputs: false, createChasePhase
  });
}

const arenaTransition = Object.create(ToyRoomArenaPhase.prototype);
arenaTransition.battle = { state: { mode: 'VICTORY', player: { hp: 3 }, history: [] } };
arenaTransition.room = { clearInput() {} };
arenaTransition.state = { status: 'COMBAT' };
arenaTransition.beginReturn();
assert.equal(arenaTransition.state.status, 'RETURNING');
assert.equal(arenaTransition.state.destination, 'CHASE');

const defeatTransition = Object.create(ToyRoomArenaPhase.prototype);
defeatTransition.battle = { state: { mode: 'DEFEAT', player: { hp: 0 }, history: [] } };
defeatTransition.room = { clearInput() {} };
defeatTransition.state = { status: 'COMBAT' };
defeatTransition.beginReturn();
assert.equal(defeatTransition.state.destination, 'ROOM');

const room = makeRoom();
room.arena.start();
Object.assign(room.arena.state, {
  status: 'RETURNING', outcome: 'VICTORY', destination: 'CHASE',
  transitionElapsed: 0, returnElapsed: 0
});
room.update(12);
room.update(12);
assert.equal(room.chase, null, 'A fuga não começa antes de a tela escurecer.');
room.update(6);
assert.equal(room.arena.state.status, 'COMPLETE');
assert.equal(room.battle.state, null);
assert.equal(room.story.state.arenaCompleted, true);
assert.equal(room.organizedCount, room.toys.length);
assert.equal(room.chase?.campaign, true);
assert.equal(starts.filter(item => item.campaign).length, 1);
assert.ok(room.arena.state.transitionElapsed >= ARENA_VICTORY_FADE_DURATION);

const savedCampaign = JSON.parse(JSON.stringify(room.snapshot()));
assert.equal(savedCampaign.toyRoomChaseCampaign.state.stage, 'BEAR_DOWN');
const resumed = makeRoom();
resumed.restore(savedCampaign);
assert.equal(resumed.chase?.campaign, true);
assert.deepEqual(starts.at(-1).saved, savedCampaign.toyRoomChaseCampaign);

const preview = makeRoom();
await preview.startChasePreview();
assert.equal(preview.snapshot().toyRoomChaseCampaign, undefined, 'A prévia não contamina o save da campanha.');
const oldSave = JSON.parse(JSON.stringify(makeRoom().snapshot()));
const legacy = makeRoom();
legacy.restore(oldSave);
assert.equal(legacy.chase, null, 'Saves sem a nova etapa continuam válidos.');

for (const instance of [room, resumed, preview, legacy]) instance.destroy();
console.log('APROVADO: vitória encadeia a fuga após o fade, derrota mantém retorno à sala, save de campanha retoma BEAR_DOWN e prévia/saves antigos permanecem isolados.');
